const normalizeCode = (code: string): string =>
  code.replace(/^:+|:+$/g, '').toLowerCase()

let byCode: Map<string, ForumEmoji> | null = null

export const getEmojiByCode = (code: string): ForumEmoji | undefined => {
  if (!byCode) {
    byCode = new Map()
    for (const group of EMOJI_GROUPS) {
      for (const emoji of group.emojis) {
        for (const alias of emoji.codes) {
          const key = normalizeCode(alias)
          if (key && !byCode.has(key)) byCode.set(key, emoji)
        }
      }
    }
  }
  return byCode.get(normalizeCode(code))
}
